SELECT ?z ?air ?ts WHERE {
  ?z a brick:Zone .
  FILTER(str(?z) = "Perimeter_ZN_4" || str(?z) = "Perimeter_ZN_1")
  ?z brick:hasPoint ?p .
  ?p a brick:AirTemperature .
  ?p ref:hasTimeseriesId ?ts
  OPTIONAL { ?z rdfs:label ?lbl }
}

SELECT ?z ?lbl WHERE {
  ?z a brick:Zone .
  OPTIONAL{?z rdfs:label ?lbl}
}

SELECT DISTINCT ?cls WHERE {
  ?x a ?cls .
  FILTER(str(?cls) = "brick:Zone" || str(?cls) = "https://brickschema.org/schema/Brick#Zone")
}

SELECT ?z ?lbl ?p ?pt ?ts WHERE {
  ?z a brick:HVAC_Zone .
  OPTIONAL{?z rdfs:label ?lbl}
  ?z brick:hasPoint ?p .
  OPTIONAL{?p a ?pt . FILTER(str(?pt)="https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor" || str(?pt)="https://brickschema.org/schema/Brick#Air_Temperature_Sensor")}
  OPTIONAL{?p ref:hasTimeseriesId ?ts}
}

